require_once __DIR__.'/../includes/bootstrap.php';require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$edit=$id>0;$u=$edit?find_user($id):null;if($edit&&!$u){set_flash('error','User not found.');redirect('admin/users.php');}$errors=[];$name=$u['full_name']??'';$email=$u['email']??'';$phone=$u['phone']??'';$role=$u['role']??'user';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$role=$_POST['role']??'user';$pw=$_POST['password']??'';if(!valid_name($name))$errors[]='Name must be 2–100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if($phone!==''&&!preg_match('/^[0-9+() .-]{7,20}$/',$phone))$errors[]='Invalid phone.';if(!in_array($role,['user','admin'],true))$errors[]='Invalid role.';if((!$edit||$pw!=='')&&!strong_password($pw))$errors[]='Password needs 8+ characters with letters and numbers.';$s=db()->prepare('SELECT id FROM users WHERE email=? AND id<>?');$s->execute([$email,$id]);if($s->fetch())$errors[]='Email already in use.';if($edit&&$id===(int)current_user()['id']&&$role!=='admin')$errors[]='You cannot remove your own admin role.';
if(!$errors){if($edit){if($pw!==''){$s=db()->prepare('UPDATE users SET full_name=?,email=?,phone=?,role=?,password_hash=? WHERE id=?');$s->execute([$name,$email,$phone?:null,$role,password_hash($pw,PASSWORD_DEFAULT),$id]);}else{$s=db()->prepare('UPDATE users SET full_name=?,email=?,phone=?,role=? WHERE id=?');$s->execute([$name,$email,$phone?:null,$role,$id]);}if($id===(int)current_user()['id']){$_SESSION['user']['full_name']=$name;$_SESSION['user']['email']=$email;$_SESSION['user']['role']=$role;}set_flash('success','User updated.');}else{$s=db()->prepare('INSERT INTO users(full_name,email,phone,password_hash,role) VALUES(?,?,?,?,?)');$s->execute([$name,$email,$phone?:null,password_hash($pw,PASSWORD_DEFAULT),$role]);set_flash('success','User created.');}redirect('admin/users.php');}}
render_header($edit?'Edit user':'Add user');?><section class="heading"><div><p class="eyebrow">USER MANAGEMENT</p><h1><?=$edit?'Edit user':'Add user'?></h1></div><a class="btn secondary" href="<?=e(BASE_URL)?>/admin/users.php">← Back</a></section><section class="panel form-panel narrow"><?php if($errors):?><div class="alert error"><?php foreach($errors as $x)echo '<p>'.e($x).'</p>';?></div><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><label>Full name *<input name="full_name" required value="<?=e($name)?>"></label><label>Email *<input type="email" name="email" required value="<?=e($email)?>"></label><label>Phone<input name="phone" value="<?=e($phone??'')?>"></label><label>Role<select name="role"><option value="user" <?=$role==='user'?'selected':''?>>User</option><option value="admin" <?=$role==='admin'?'selected':''?>>Admin</option></select></label><label><?=$edit?'New password (optional)':'Temporary password *'?><input type="password" name="password" <?=$edit?'':'required'?>><small><?=$edit?'Leave blank to keep existing password.':'At least 8 characters, letters and numbers.'?></small></label><button class="btn"><?=$edit?'Save changes':'Create user'?> →</button></form></section><?php render_footer();?>
